import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.D5wUhsuj.js";const h=JSON.parse('{"title":"PhyAgentOS Communication Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"user_development_guide/COMMUNICATION_en.md","filePath":"user_development_guide/COMMUNICATION_en.md"}'),i={name:"user_development_guide/COMMUNICATION_en.md"};function s(r,e,l,d,c,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="phyagentos-communication-architecture" tabindex="-1">PhyAgentOS Communication Architecture <a class="header-anchor" href="#phyagentos-communication-architecture" aria-label="Permalink to &quot;PhyAgentOS Communication Architecture&quot;">​</a></h1><p><a href="/docs/user_development_guide/COMMUNICATION">中文</a> · <a href="/docs/en/">Documentation index</a></p><blockquote><p>Version: 1.0.0</p></blockquote><h2 id="_1-communication-boundaries" tabindex="-1">1. Communication boundaries <a class="header-anchor" href="#_1-communication-boundaries" aria-label="Permalink to &quot;1. Communication boundaries&quot;">​</a></h2><p>PhyAgentOS separates six boundaries:</p><ol><li>user/channel ↔ AgentLoop messages;</li><li>Agent tools ↔ AgentTaskCoordinator;</li><li>ForgeToolClient ↔ Gateway Query/Action/Session Tool API;</li><li>observation collector ↔ Gateway image/state WebSockets;</li><li>verifier ↔ isolated Verification Service;</li><li>AgentTask/experience/Runtime ↔ their own persistent stores.</li></ol><p>The boundaries share opaque references, not execution ownership.</p><h2 id="_2-user-message-boundary" tabindex="-1">2. User-message boundary <a class="header-anchor" href="#_2-user-message-boundary" aria-label="Permalink to &quot;2. User-message boundary&quot;">​</a></h2><p>Channels publish <code>InboundMessage</code> objects to the Agent bus. AgentLoop builds context, invokes the model and tools, then emits <code>OutboundMessage</code>. Tool calls use registered JSON schemas. The existing file, directory, shell, web, messaging, image, Scene Graph, Cron, Spawn, Agent Mode, Skill activation, and dynamic MCP tools follow this same loop.</p><p>AgentTask&#39;s <code>origin_session_key</code> associates completion experience with the originating Agent conversation. It is not a Gateway execution identifier.</p><h2 id="_3-agenttask-boundary" tabindex="-1">3. AgentTask boundary <a class="header-anchor" href="#_3-agenttask-boundary" aria-label="Permalink to &quot;3. AgentTask boundary&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>forge_task_create</span></span>
<span class="line"><span>forge_task_get</span></span>
<span class="line"><span>forge_task_begin_revision</span></span>
<span class="line"><span>forge_task_finalize</span></span>
<span class="line"><span>forge_task_cancel</span></span></code></pre></div><p>These tools call AgentTaskCoordinator and never call Dora or a robot. The coordinator uses transactional SQLite to enforce one non-terminal AgentTask and stores append-only PlanRevisions, Tool records, evidence references, and verification attempts.</p><p>Diagnostic Query may omit <code>task_id</code>; governed Query and every Action/Session include it. The wrapper checks the immutable Skill/Runtime/ToolSpec binding and creates or updates the matching Tool record around the same Gateway request. This is aggregation, not another execution plane.</p><h2 id="_4-gateway-http-boundary" tabindex="-1">4. Gateway HTTP boundary <a class="header-anchor" href="#_4-gateway-http-boundary" aria-label="Permalink to &quot;4. Gateway HTTP boundary&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET  /tools</span></span>
<span class="line"><span>GET  /tools/{tool_id}</span></span>
<span class="line"><span>GET  /tools/{tool_id}/context</span></span>
<span class="line"><span>POST /tools/{endpoint_id}/{operation}:invoke   # Query, HTTP 200</span></span>
<span class="line"><span>POST /tools/{tool_id}:invoke                   # Action/Session admission, HTTP 202</span></span>
<span class="line"><span>GET  /invocations/{invocation_id}</span></span>
<span class="line"><span>GET  /invocations/{invocation_id}/result       # HTTP 202 while pending</span></span>
<span class="line"><span>POST /invocations/{invocation_id}/cancel</span></span>
<span class="line"><span>POST /invocations/{invocation_id}/stop         # Session</span></span></code></pre></div><p>Query invocation first reads the ToolSpec and uses its <code>endpoint_id</code>, <code>operation</code>, and <code>semantics=query</code> binding. Action/Session invocation addresses the stable Tool ID; both return an <code>invocation_id</code>, and Action also returns an <code>attempt_id</code>.</p><p>Every successful response is a JSON object with <code>ok=true</code> and object-valued <code>data</code>. Error envelopes may carry code and retryability. A transport timeout means remote state is unknown. Returned invocation identities must be retained even if later local persistence or tracking fails.</p><h2 id="_5-identity-boundary" tabindex="-1">5. Identity boundary <a class="header-anchor" href="#_5-identity-boundary" aria-label="Permalink to &quot;5. Identity boundary&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Identity</th><th style="text-align:left;">Namespace</th><th style="text-align:left;">Mutability</th></tr></thead><tbody><tr><td style="text-align:left;"><code>task_id</code></td><td style="text-align:left;">PAOS AgentTask</td><td style="text-align:left;">Stable for all revisions</td></tr><tr><td style="text-align:left;"><code>binding_id</code></td><td style="text-align:left;">PAOS Forge binding</td><td style="text-align:left;">Immutable Skill/Runtime/ToolSpec snapshot</td></tr><tr><td style="text-align:left;"><code>revision_id</code></td><td style="text-align:left;">PAOS PlanRevision</td><td style="text-align:left;">Immutable, append-only generation</td></tr><tr><td style="text-align:left;"><code>record_id</code></td><td style="text-align:left;">PAOS ToolExecutionRecord</td><td style="text-align:left;">Immutable record identity</td></tr><tr><td style="text-align:left;"><code>caller_id</code></td><td style="text-align:left;">PAOS ToolExecutionRecord</td><td style="text-align:left;">Persisted before asynchronous admission</td></tr><tr><td style="text-align:left;"><code>invocation_id</code></td><td style="text-align:left;">Gateway ToolInvocation</td><td style="text-align:left;">Stable Action/Session lifecycle identity</td></tr><tr><td style="text-align:left;"><code>attempt_id</code></td><td style="text-align:left;">Gateway attempt</td><td style="text-align:left;">Stable for the returned attempt</td></tr></tbody></table><p>No component derives one namespace from another. Correlation happens by explicit stored references.</p><h2 id="_6-invocation-terminal-semantics" tabindex="-1">6. Invocation terminal semantics <a class="header-anchor" href="#_6-invocation-terminal-semantics" aria-label="Permalink to &quot;6. Invocation terminal semantics&quot;">​</a></h2><p>Gateway status/result is the only Action/Session terminal source. Pending remains non-terminal. Known terminal values include success, failure, cancellation, or stopped as reported by Gateway. <code>unknown</code> is terminal for PAOS accounting because progress cannot be proven, but it is not a known physical stop and remains tracked for normal Runtime-stop gating.</p><p>Cancellation/stop <code>requested</code> or <code>accepted</code> acknowledges control delivery only. It does not untrack an invocation or set an AgentTask to cancelled. PAOS continues reconciliation and finalizes the task explicitly.</p><h2 id="_7-evidence-websocket-boundary" tabindex="-1">7. Evidence WebSocket boundary <a class="header-anchor" href="#_7-evidence-websocket-boundary" aria-label="Permalink to &quot;7. Evidence WebSocket boundary&quot;">​</a></h2><p>PAOS connects to configured image and optional state streams using bounded connection and capture timeouts. Messages are treated as untrusted input. Image media, decoded size, sequence, phase, source, local receive time, and SHA-256 are validated before persistence.</p><p>The collector captures before the first bound physical execution and after task-owned executions reach terminal accounting state. Evidence association is best-effort; Gateway ToolResult and invocation events remain authoritative for execution.</p><h2 id="_8-verification-boundary" tabindex="-1">8. Verification boundary <a class="header-anchor" href="#_8-verification-boundary" aria-label="Permalink to &quot;8. Verification boundary&quot;">​</a></h2><p>The Agent-side verifier sends resolved public task contracts, normalized Tool facts, evidence, history, and frozen scoped Lessons to the isolated Verification Service. Lessons are untrusted, non-authoritative advice. The service cannot invoke Gateway, create a PlanRevision, or change execution records.</p><p>Verifier output must validate as the versioned verdict contract. AgentTaskCoordinator applies <code>off</code>, <code>audit</code>, <code>enforce</code>, or <code>recovery</code> semantics and persists every attempt.</p><h2 id="_9-experience-boundary" tabindex="-1">9. Experience boundary <a class="header-anchor" href="#_9-experience-boundary" aria-label="Permalink to &quot;9. Experience boundary&quot;">​</a></h2><p>ExperienceCoordinator receives an AgentTask completion reference. <code>AgentTaskOutcomeSource</code> builds a redacted envelope containing workflow structure, semantic verdicts, field names, and opaque task, revision, invocation, attempt, and evidence references. Raw arguments, results, credentials, endpoints, and physical coordinates are not copied into learned content.</p><p>The episode is unique per AgentTask. PlanRevisions, repeated completion notifications, reviews, and replay do not create independent support.</p><h2 id="_10-persistence-boundary" tabindex="-1">10. Persistence boundary <a class="header-anchor" href="#_10-persistence-boundary" aria-label="Permalink to &quot;10. Persistence boundary&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Store</th><th style="text-align:left;">Content</th></tr></thead><tbody><tr><td style="text-align:left;"><code>.paos/agent_tasks/tasks.sqlite3</code></td><td style="text-align:left;">AgentTask records and append-only events</td></tr><tr><td style="text-align:left;"><code>artifacts/agent_tasks/&lt;task_id&gt;/</code></td><td style="text-align:left;">Before/after snapshots, bundle metadata, evidence entities</td></tr><tr><td style="text-align:left;"><code>.paos/evolution/experience.sqlite3</code></td><td style="text-align:left;">Bindings, episodes, Lessons, candidates, jobs, events</td></tr><tr><td style="text-align:left;">Skill Runtime state path</td><td style="text-align:left;">Installed Runtime state, invocation/Session IDs, task bindings, and audit events</td></tr><tr><td style="text-align:left;">Skill Runtime logs path</td><td style="text-align:left;">Lifecycle and Dora launch logs</td></tr></tbody></table><p>SQLite updates and artifact writes are transactional or atomic within their own boundary. A Gateway response is not rolled back because local experience processing failed; evolution is fail-open.</p><h2 id="_11-skill-runtime-and-registry-boundary" tabindex="-1">11. Skill Runtime and Registry boundary <a class="header-anchor" href="#_11-skill-runtime-and-registry-boundary" aria-label="Permalink to &quot;11. Skill Runtime and Registry boundary&quot;">​</a></h2><p>Registry/index clients return artifact metadata and downloads. Cache and installers require size and SHA-256, then validate archive inventories and exact single-executable Node locks before atomic installation. RuntimeManager starts a named Dora flow and observes Gateway <code>/tools</code>; it never calls an alternate Gateway Agent API.</p><p>The active Runtime availability provider supplies Skill visibility and Gateway URL to the Agent. It does not mutate AgentTask or experience data.</p><h2 id="_12-trust-rules" tabindex="-1">12. Trust rules <a class="header-anchor" href="#_12-trust-rules" aria-label="Permalink to &quot;12. Trust rules&quot;">​</a></h2><ul><li>Treat ToolSpec, Gateway responses, WebSocket payloads, task text, and learned text as untrusted data.</li><li>Never log credentials or raw sensitive task inputs.</li><li>Never infer stop from cancel acceptance, timeout, or unknown.</li><li>Never bypass digest or archive safety checks.</li><li>Never place a second execution API between Agent tools and ForgeToolClient.</li><li>Keep Runtime force-stop and destructive artifact cleanup as explicit operator actions.</li></ul><h2 id="next-reading" tabindex="-1">Next reading <a class="header-anchor" href="#next-reading" aria-label="Permalink to &quot;Next reading&quot;">​</a></h2><ul><li><a href="/docs/user_development_guide/README_en">Integration Development Guide</a></li><li><a href="/docs/user_manual/README_en">Operations Manual</a></li><li><a href="/docs/forge/README">Forge Tool API Contract</a></li></ul>`,43)])])}const g=t(i,[["render",s]]);export{h as __pageData,g as default};
